// Раздел «Графика» (шаг 19): рендер, качество, свет, частицы
function artHelp() {
  const A = window.Art, s = (A && A.settings) || {};
  return `<h3 id="h-gfx">Графика</h3>
  <ul>
    <li><b>Размер текста</b>: Меню → Доступность → Размер текста, малый (80%), средний (90%), нормальный (100%), большой (150%) и огромный (200%). Меняется сразу и сохраняется в браузере. Увеличиваются надписи в панелях, чате, подсказках, имена и числа урона на карте. Кнопка «Обычный размер» возвращает 100%.</li>
    <li>Герои, спутники, противники и транспорт имеют восемь направлений. Движение, ближний удар, выстрел и чтение магии используют разные позы и эффекты.</li>
    <li><b>Автобой</b> — внизу справа, над автолутом: «Ближний», «Дальний», «Магия». Режимы можно сочетать. Магия использует изученные заклинания на панели 1–0, учитывает ману и откаты; лечение применяется при нехватке здоровья. Ручное перемещение временно приостанавливает автобой.</li>
    <li><b>Миникарта</b>: «+» и «−» меняют масштаб, «⟲» возвращает обзор всей карты. При увеличении карта следует за героем; можно пользоваться колёсиком мыши. Масштабы миникарты и основного вида сохраняются в этом браузере между входами в игру.</li>
    <li><b>Четыре режима окружения</b>: домик вверху справа — 1) всё целиком; 2) низкие остатки, пни и основания; 3) полупрозрачные участки только в радиусе героя; 4) круглый срез сферой: внутри остаются низкие основания, за границей объекты целые. Радиус автоматически равен наибольшей дальности надетого и бортового оружия и изученной магии. Меню → «Обзор окружения»: выбор режима и прозрачность. Настройки сохраняются; столкновения и туман войны сохраняются.</li>
    <li><b>Художественный рендер</b> (по умолчанию): текстуры почвы по биомам с плавными переходами, объекты (руины, ржавые машины, деревья, скалы, кристаллы), постройки базы и поселений,
    анимации ходьбы, удара, попадания и смерти, свет дня и ночи, частицы магии и боя. Все картинки рисуются кодом при запуске — никаких загрузок.</li>
    <li><b>Качество</b> (Меню → «Качество»): <i>низкое</i> — без переходов, теней и частиц, ровный свет (для слабых ПК); <i>среднее</i> — всё включено, частиц вдвое меньше; <i>высокое</i> — больше деталей и частиц. Меняется сразу.</li>
    <li><b>Рендер</b> (Меню → «Рендер»): «простой (прежний)» — старый рисунок без текстур; включается при следующем входе в мир. Если художественный рендер не смог запуститься, игра сама переходит на простой.</li>
    <li><b>Свет</b>: ночью темнее (до ${Math.round((s.artNightDark ?? 0.45) * 100)}% затемнения), на рассвете и закате — тёплый оттенок; под землёй видно ~${s.artUnderLight ?? 7} клеток вокруг героя, под водой — синий полумрак.</li>
    <li>Дети в семье выглядят по-разному: рост зависит от возраста, волосы, кожа и одежда — свои у каждого.</li>
    <li>Выбор сохраняется в этом браузере. Серверные настройки: <code>graphicsRenderer</code>, <code>graphicsQuality</code>, <code>artParticleMax</code> и др. (см. <code>--help</code>).</li>
  </ul>`;
}
// Разделы «Чит-панель» и «Производительность и сеть» (шаг 20)
